import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('herpes-simplex-labialis',
  kf=["Recurrent **HSV-1** infection of the lip border: tingling, then grouped **vesicles**, crusting and healing in 7–10 days.",
      "Most adults carry HSV-1; the virus lies **latent in the trigeminal ganglion** and reactivates with sun, fever, stress, menstruation or trauma.",
      "Infectious from tingling until fully crusted; also spread by **asymptomatic shedding**.",
      "Self-care and OTC aciclovir cream for mild episodes; oral antiviral for severe, frequent or immunocompromised cases.",
      "Same-day assessment for **eczema herpeticum**, eye involvement, neonates and the immunocompromised."],
  epi=[{"t": "**Very common**", "sub": ["HSV-1 seroprevalence rises with age: most adults worldwide; under half of UK university entrants (less childhood exposure).", "About 20–40% of infected people get recurrent cold sores."]},
       {"t": "**Primary infection**", "sub": ["Usually in childhood, often silent or as **gingivostomatitis**; HSV-2 mainly after puberty (genital)."]}],
  aet=["**Triggers for recurrence**: UV light, fever and colds, stress, fatigue, menstruation, lip trauma, dental work, immunosuppression.",
       "Transmission by kissing, sharing cups or towels; infectious for about 7–12 days per episode."],
  myths=["**\"Cold sores only spread when visible\"**: asymptomatic shedding can transmit HSV.", "**\"Antiviral cream cures it\"**: it only shortens episodes if started at the first tingle."],
  patho_lead="HSV is a **neurotropic** DNA virus: it hides in sensory ganglia and travels along nerves to the skin.",
  mech=[("Primary infection", "Virus enters through mucosa or broken skin, replicates in keratinocytes and travels up sensory nerves.", "v3-hsv-ganglion.jpg", "Latent HSV in the trigeminal ganglion and its path along the nerve to the lip."),
        ("Latency", "HSV persists **latent in the trigeminal ganglion** for life, invisible to the immune system."),
        ("Reactivation", "Triggers (UV, fever, stress) reactivate the virus, which travels down the nerve: **prodromal tingling or burning** for 6–48 hours."),
        ("Vesicles and healing", "Viral replication in keratinocytes causes ballooning and cell fusion, giving clustered vesicles that ulcerate, crust and heal in 7–10 days.", "v3-hsv-stages.jpg", "Stages of a cold sore: tingle, vesicles, ulcer, crust, healing.")],
  histo=["Intraepidermal vesicle with **ballooning degeneration**, multinucleated giant cells and nuclear moulding (Tzanck smear).", "Diagnosis is clinical; viral PCR swab if atypical, severe or immunocompromised."],
  special=[{"t": "**Atopic eczema**", "sub": ["Risk of **eczema herpeticum** (widespread punched-out erosions, fever): emergency."]},
           {"t": "**Neonates and pregnancy**", "sub": ["Avoid kissing newborns during an episode; neonatal HSV is life-threatening."]},
           {"t": "**Immunocompromised**", "sub": ["Large, persistent or atypical ulcers; needs oral or IV antivirals and specialist advice."]}],
  comp=["Eczema herpeticum (Kaposi varicelliform eruption).", "Herpetic keratitis and eye involvement.", "Herpetic whitlow (finger).", "Secondary impetigo.", "**Erythema multiforme** triggered by recurrent HSV.", "Rarely encephalitis or disseminated infection."],
  prog=["Lifelong latent infection; recurrences often become less frequent with age.", "Episodes heal without scarring in 7–10 days."],
  see_also=["herpes-zoster", "erythema-multiforme", "impetigo", "eczema-dermatitis"])

E('head-lice',
  kf=["Infestation of the scalp hair by the louse ***Pediculus humanus capitis***.",
      "Very common in children aged **4–14**; spread by **head-to-head contact** (lice crawl, they cannot jump or fly).",
      "Diagnose only by finding a **live louse** with wet or dry **detection combing**; nits alone do not prove active infestation.",
      "Options: **wet combing** (bug busting) or a physically acting product such as **dimeticone 4%**, repeated after 7 days.",
      "Check all household members and treat only those with live lice; children need not miss school."],
  epi=[{"t": "**Who**", "sub": ["Worldwide, all social groups; commonest in primary-school children, more often **girls** (longer hair, closer contact)."]},
       {"t": "**Spread**", "sub": ["Direct head-to-head contact; sharing brushes or hats is a minor route."]}],
  aet=["Risk factors: female sex, more children in the family, sharing beds, combs and hats.", "Resistance to older insecticides (permethrin, malathion) is widespread, so physical or mechanical methods are preferred."],
  myths=["**\"Lice mean dirty hair\"**: lice prefer clean or dirty hair equally.", "**\"Lice jump\"**: they crawl from hair to hair.", "**\"Nits mean active lice\"**: empty egg cases stay glued to hair for months."],
  patho_lead="The louse lives on the scalp and feeds on blood; itch is an **allergic reaction** to its saliva.",
  mech=[("Eggs glued to hair", "Females lay up to 10 eggs a day, cemented to the hair shaft close to the scalp; they hatch in 7–10 days.", "v3-headlice-nits.jpg", "Louse and nits (eggs) glued close to the scalp on the hair shaft."),
        ("Nymphs mature", "Nymphs become adults in about 7–10 days; adults live about 30 days and die within 1–2 days off the head."),
        ("Feeding and itch", "Lice feed on blood several times a day; sensitisation to saliva causes **itch after 4–6 weeks** of a first infestation."),
        ("Detection", "Combing wet, conditioned hair with a fine-toothed comb is the most reliable way to find live lice.", "v3-lice-detection-comb.jpg", "Detection combing in sections from the scalp to the ends.")],
  histo=["Not relevant; diagnosis is by detection combing and seeing a live louse."],
  comp=["Scalp **excoriations and dermatitis**; secondary bacterial infection (impetigo) and enlarged neck nodes.", "Anxiety, stigma and school disruption."],
  prog=["Curable; reinfestation from untreated contacts is common.", "Treatment failure is usually due to incorrect use, resistance or reinfestation."],
  see_also=["scabies", "impetigo", "papular-urticaria-bites"])

E('folliculitis',
  kf=["Inflammation of hair follicles: **follicular papules and pustules** centred on hairs.",
      "Most often bacterial (*Staphylococcus aureus*); also *Malassezia*, *Pseudomonas* (hot tubs), Gram-negative, viral and non-infective causes.",
      "Triggers: shaving, waxing, occlusion, sweating, friction, topical steroids and antibiotics.",
      "Mild: antiseptic washes and stop the trigger; persistent bacterial: topical or oral antibiotic per culture; *Malassezia*: antifungals.",
      "Deep or spreading infection (furuncle, cellulitis) needs review."],
  epi=[{"t": "**Who**", "sub": ["Common at all ages worldwide; most often adolescents and young adult men.", "Pseudofolliculitis barbae is especially common in men with tightly curled hair."]}],
  aet=["**Infective**: *S. aureus* (commonest), coagulase-negative staphylococci, *Pseudomonas* (spa pools), Gram-negative (after long antibiotic use for acne), *Malassezia*, dermatophytes, HSV, *Demodex*.",
       "**Non-infective**: shaving (pseudofolliculitis), occlusion and oils, drugs (steroids, EGFR inhibitors, lithium), eosinophilic folliculitis (HIV).",
       "**Host factors**: atopic eczema, diabetes, obesity, immunosuppression, nasal *S. aureus* carriage."],
  patho_lead="The level of the follicle that is inflamed decides how the lesion looks and how deep the risk goes.",
  mech=[("Follicle damage", "Shaving, friction or occlusion damage the follicular opening and let organisms in.", "v3-follicle-depths.jpg", "Superficial folliculitis (top of the follicle), furuncle (deep follicle abscess) and carbuncle (linked follicles)."),
        ("Superficial folliculitis", "Organisms multiply in the upper follicle; neutrophils gather into a small pustule pierced by a hair."),
        ("Deep folliculitis", "Inflammation extends down the follicle into the dermis (sycosis, furuncle), giving tender nodules and possible scarring."),
        ("Ingrowing hairs", "In pseudofolliculitis, tightly curled hairs re-enter the skin after shaving, causing a foreign-body reaction.", "v3-pfb-section.jpg", "Pseudofolliculitis: a curled hair re-entering the skin next to its follicle.")],
  histo=["Neutrophils in and around the follicle; organisms on Gram or PAS stain.", "Swab pustules for culture when persistent, recurrent or after long antibiotic use."],
  special=[{"t": "**Skin of colour**", "sub": ["Pseudofolliculitis barbae and keloidal scarring are common; post-inflammatory hyperpigmentation is often the main concern."]}],
  comp=["Furuncles and carbuncles; cellulitis.", "Scarring, keloids and permanent hair loss in deep or chronic forms.", "Post-inflammatory pigmentation."],
  prog=["Superficial folliculitis usually settles in days to weeks once the trigger is removed.", "Recurrence is common with ongoing shaving, occlusion or carriage."],
  see_also=["boils-carbuncles", "acne-mimics", "acne-vulgaris", "impetigo"])

E('boils-carbuncles',
  kf=["A **boil (furuncle)** is a deep *Staphylococcus aureus* infection of a hair follicle forming a painful abscess; a **carbuncle** is several linked boils.",
      "Common in adolescents and adults; risk factors include nasal carriage, diabetes, obesity, friction and close contact.",
      "Small boils: warm compresses; large or fluctuant: **incision and drainage**.",
      "Antibiotics (e.g. flucloxacillin) only if systemically unwell, spreading cellulitis, high-risk site or comorbidity (CKS).",
      "Recurrent boils: swab, consider **PVL-producing *S. aureus*** and decolonisation."],
  epi=[{"t": "**Who**", "sub": ["Common in adolescents and young adults; outbreaks in families, sports teams, prisons and the military."]}],
  aet=["**Organism**: *S. aureus*, including MRSA and **Panton–Valentine leukocidin (PVL)**-producing strains (recurrent, multiple, necrotic boils).",
       "**Risk factors**: nasal or perineal carriage, diabetes, obesity, immunosuppression, eczema, friction, shaving, poor hygiene, close contact and shared towels."],
  myths=["**\"Squeeze it to clear it\"**: squeezing can spread infection; drain only when fluctuant and by a clinician."],
  patho_lead="A boil is a **follicular abscess**: neutrophils wall off staphylococci deep in the follicle.",
  mech=[("Follicle invasion", "*S. aureus* enters a damaged follicle and spreads deep into it.", "v3-follicle-depths.jpg", "From superficial folliculitis to a deep follicular abscess (boil) and a carbuncle."),
        ("Abscess formation", "Neutrophils and necrotic tissue form pus; a red, hot, tender nodule becomes **fluctuant** with a yellow point."),
        ("Carbuncle", "Infection spreads through connected follicles in thick skin (back of neck, back, thighs), forming a larger mass with several heads.", "v3-boil-vs-carbuncle.jpg", "Single boil vs carbuncle with multiple draining heads."),
        ("Drainage and healing", "Pus discharges spontaneously or after incision; warm compresses help it point.", "v3-boil-warm-compress.jpg", "Warm compress to help a small boil come to a head.")],
  histo=["Dense neutrophilic abscess centred on a follicle with necrosis; Gram-positive cocci.", "Swab pus for culture and sensitivity (and PVL if recurrent)."],
  comp=["Cellulitis, lymphangitis; scarring.", "Bacteraemia, osteomyelitis, endocarditis (rare).", "Facial 'danger triangle' boils: rare cavernous sinus thrombosis.", "PVL strains: necrotising soft-tissue infection and necrotising pneumonia."],
  prog=["Most heal within 1–2 weeks after draining.", "Recurrence is common with carriage; decolonisation helps some."],
  see_also=["folliculitis", "cellulitis-erysipelas", "hidradenitis-suppurativa", "skin-cysts"])

E('pityriasis-rosea',
  kf=["Self-limiting rash of young people: a **herald patch** then oval pink patches with a **collarette of scale** in a 'Christmas tree' pattern on the trunk.",
      "Incidence about **0.5–2%**; most common at **10–35 years**, often in spring and autumn.",
      "Probably triggered by reactivation of **HHV-6/7**; not contagious in practice.",
      "Reassure; emollient and a mild or moderate topical steroid or antihistamine for itch. Resolves in **6–12 weeks**.",
      "In **pregnancy** (first 15 weeks) there are reports of miscarriage: inform the obstetric team. Consider secondary syphilis if palms or soles are involved."],
  epi=[{"t": "**Who**", "sub": ["Teenagers and young adults (10–35 years); slightly more common in women.", "Incidence about 0.5–2%; seasonal clustering in spring and autumn."]},
       {"t": "**Recurrence**", "sub": ["Uncommon (about 2–3%)."]}],
  aet=["**HHV-6 and HHV-7** reactivation is the strongest association.", "**Drug-induced** PR-like eruptions: ACE inhibitors, NSAIDs, metronidazole, isotretinoin, imatinib and others.",
       "Reported after vaccines (BCG, influenza, COVID-19) and viral infections."],
  myths=["**\"It's ringworm\"**: tinea has an advancing scaly edge; PR has trailing scale just inside the edge.", "**\"It's catching\"**: it is not considered contagious."],
  patho_lead="PR is thought to be a **T-cell response to reactivated HHV-6/7**, following skin tension lines.",
  mech=[("Viral reactivation", "HHV-6/7 reactivate (often after a mild viral illness), triggering a cell-mediated immune response in the skin."),
        ("Herald patch", "A single 2–5 cm oval pink patch appears first, often on the trunk."),
        ("Secondary eruption", "1–2 weeks later many smaller ovals appear along **cleavage (Langer) lines**, giving the Christmas-tree pattern.", "v3-pr-christmas-tree.jpg", "Oval patches following the ribs: the Christmas-tree pattern on the back."),
        ("Collarette scale", "Scale sits **just inside the edge**, trailing behind it, unlike tinea where scale is at the advancing edge.", "v3-collarette-vs-tinea-edge.jpg", "Pityriasis rosea collarette (trailing scale) vs tinea (scale at the advancing edge).")],
  histo=["Mild spongiosis with focal parakeratosis (mounds), extravasated red cells and a superficial perivascular lymphocytic infiltrate.", "Biopsy only if atypical or persistent beyond 3 months."],
  special=[{"t": "**Skin of colour**", "sub": ["Lesions look grey-brown or violaceous; papular and inverse (flexural) forms are more common; pigment change can persist."]},
           {"t": "**Pregnancy**", "sub": ["Possible link with miscarriage in the first 15 weeks: inform the obstetric team."]}],
  comp=["Itch; post-inflammatory hyper- or hypopigmentation lasting months.", "Pregnancy complications (rare reports)."],
  prog=["Resolves spontaneously in 6–12 weeks; recurrence is uncommon."],
  see_also=["psoriasis", "tinea", "annular-rashes", "pityriasis-versicolor"])

E('pityriasis-versicolor',
  kf=["Superficial infection with the lipophilic yeast ***Malassezia*** causing scaly **hypo- or hyperpigmented** patches on the upper trunk.",
      "Most common in **young adults**, hot humid climates and people who sweat heavily; recurs each summer.",
      "**Fine scale** shows when the skin is stretched or scraped; Wood's light may give yellow fluorescence.",
      "First line (CKS): **ketoconazole 2% shampoo** as a short-contact wash; topical azole for small areas; oral itraconazole if extensive or resistant.",
      "Colour takes **months** to normalise after the yeast is cleared; recurrence is common (prophylaxis may help)."],
  epi=[{"t": "**Who**", "sub": ["Young adults, slightly more men; up to 40% in tropical climates, 1–4% in temperate climates.", "Malassezia is normal flora in 90–100% of adults."]}],
  aet=["**Organisms**: *M. globosa*, *M. sympodialis*, *M. furfur*.", "Triggers: heat, humidity, sweating, oily skin, occlusive clothing, immunosuppression, pregnancy, genetic predisposition."],
  myths=["**\"The white patches are vitiligo\"**: PV patches are scaly and fade after treatment; vitiligo is smooth and depigmented.", "**\"It's contagious\"**: it comes from your own skin yeast."],
  patho_lead="Normal skin yeast switches to a **hyphal form** and alters pigment in the stratum corneum.",
  mech=[("Yeast to hyphae", "Heat, humidity and sebum let *Malassezia* convert from yeast to the invasive **mycelial** form in the stratum corneum."),
        ("Hypopigmentation", "The yeast produces **azelaic acid** and other dicarboxylic acids that inhibit tyrosinase and melanocytes, so patches look paler, especially after a tan.", "v3-pv-back-map.jpg", "Typical distribution: scaly pale or brown patches on the upper back, chest and upper arms."),
        ("Hyperpigmentation", "In other patients, thicker keratin and inflammation make patches pink or brown."),
        ("Slow recovery", "After the yeast is killed, pigment returns only slowly over months.")],
  histo=["Short hyphae and round yeasts ('spaghetti and meatballs') in the stratum corneum on KOH microscopy of scrapings.", "Biopsy is not needed."],
  special=[{"t": "**Skin of colour**", "sub": ["Hypopigmentation is especially noticeable and distressing; reassure that colour returns slowly."]}],
  comp=["Persistent pigment change for months.", "Recurrence in up to 60% within a year and 80% within 2 years without prophylaxis."],
  prog=["Responds well to antifungals; recurrence is very common, so maintenance or seasonal prophylaxis may be offered."],
  see_also=["hypopigmentation-skin-of-colour", "tinea", "pityriasis-rosea", "folliculitis"])

E('hand-eczema',
  kf=["Common inflammatory dermatitis of the hands: **irritant**, **allergic**, **atopic** and **vesicular (pompholyx)** patterns, often mixed.",
      "Chronic hand eczema affects about **1 in 10** adults; frequent cause of time off work.",
      "High-risk jobs: healthcare, cleaning, catering, hairdressing, construction, metalwork (wet work and chemicals).",
      "Management: avoid irritants, **gloves**, frequent emollients, soap substitute, **potent topical steroid** short courses; patch test if allergy possible.",
      "Refer if severe, not responding, occupational or diagnostic doubt (tinea, psoriasis)."],
  epi=[{"t": "**Prevalence**", "sub": ["Hand dermatitis accounts for 20–35% of all dermatitis; chronic hand eczema affects 10–15% of adults.", "More common in **young adult women** and people with **atopic eczema**."]},
       {"t": "**Occupational**", "sub": ["Wet work (over 2 hours a day or frequent handwashing) is the main risk factor; leading cause of occupational skin disease."]}],
  aet=["**Irritants**: water, soaps, detergents, alcohol rubs, solvents, cutting oils, dusts, cold and friction.",
       "**Allergens**: rubber accelerators (gloves), preservatives, fragrances, chromate, nickel, hair dyes, acrylates (nails), plants.",
       "**Endogenous**: atopy, filaggrin mutations, pompholyx (often triggered by heat, sweating, stress, nickel)."],
  myths=["**\"Alcohol gel is worse than soap\"**: alcohol rubs are usually less irritant than repeated soap and water.", "**\"Gloves all day protect the skin\"**: long occlusion causes sweat irritation; use cotton liners."],
  patho_lead="Hand eczema is driven by **barrier damage** with or without an **allergic** (type IV) response.",
  mech=[("Barrier damage", "Repeated wet work and detergents strip lipids from the stratum corneum, increasing water loss and irritation.", "v3-hand-eczema-patterns.jpg", "Patterns of hand eczema: irritant (backs and finger webs), allergic (glove or contact pattern), atopic and pompholyx (vesicles on palms and sides of fingers)."),
        ("Inflammation", "Damaged keratinocytes release cytokines; in allergic cases, sensitised T cells respond to specific allergens."),
        ("Vesicles", "In pompholyx, intense spongiosis in thick palmar skin forms deep itchy **vesicles** that do not easily rupture."),
        ("Chronic changes", "Ongoing exposure causes hyperkeratosis, painful **fissures** and lichenification.")],
  histo=["Spongiotic dermatitis; pompholyx shows intraepidermal vesicles in acral skin; chronic disease shows acanthosis and hyperkeratosis.", "Scrapings exclude tinea; patch testing identifies allergens."],
  special=[{"t": "**Healthcare and catering workers**", "sub": ["Involve occupational health early; alcohol rubs plus emollients reduce irritation."]}],
  comp=["Painful fissures, secondary infection (*S. aureus*), eczema herpeticum.", "Loss of work and income; long-term disability.", "Sensitisation to treatments (gloves, preservatives)."],
  prog=["Often chronic and relapsing; only about half are clear years later, especially with atopy, allergy or continued exposure.",
        "Early diagnosis, glove use and job adaptation improve outlook."],
  see_also=["contact-dermatitis", "eczema-dermatitis", "palmoplantar-pustulosis", "keratolysis-exfoliativa"])
